import type { PropsWithChildren } from 'react';
import { ViewTransition } from 'react';
import { preload } from 'react-dom';

import files from './page-transition.files.json';

// PageTransition
// ---------------
// Dissolves the old page into the new one, cell by cell, on client
// navigations (styles in `src/css/transitions.css`, masks generated by
// `scripts/dissolve.mjs`). Wrap the outermost element of every page:
// layouts persist across navigations, so a boundary there never enters or
// exits.
export const PageTransition = ({ children }: PropsWithChildren) => {
  // Fetch the masks ahead of the first navigation, which would otherwise
  // wait for them. Masks are fetched in CORS mode, the color bands
  // (backgrounds) aren't, the preloads have to match to be reused.
  for (const href of files)
    preload(href, {
      as: 'image',
      fetchPriority: 'low',
      crossOrigin: href.includes('/mask-') ? 'anonymous' : undefined,
    });

  return (
    <ViewTransition
      enter="page-dissolve-in"
      exit="page-dissolve-out"
      default="none"
    >
      {children}
    </ViewTransition>
  );
};
